WITH prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) AS prev_started_at FROM sessions), with_gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT device, DATE_TRUNC('YEAR', prev_started_at) AS year_start, MIN(prev_started_at) AS first_prev_started_at, MIN(prev_started_at) AS first_seen, GROUPING_ID() AS gid FROM sessionized GROUP BY CUBE (device, DATE_TRUNC('YEAR', prev_started_at));
